body:
Pretty sure this is a genuine bug this time:

``` typescript
import "reflect-metadata";
import { createConnection } from "typeorm";
import { Table, PrimaryGeneratedColumn } from "typeorm";

@Table()
export class Photo {
    @PrimaryGeneratedColumn()
    id: number;
}

createConnection({
    driver: {
        type: "postgres",
        usePool: false, // No bug when set to true
        host: "localhost",
        port: 5432,
        database: "mydb",
        username: "dbuser",
        password: "mypassword"
    },
    entities: [Photo],
    autoSchemaSync: true
}).then(async (connection) => {
    console.log('hello');
    await connection.close();
    return;
}).catch((error) => {
    console.error('Error: ', error, error.stack);
});
```

